// ═══════════════════════════════════════════════════════════════════
//  ⚙️ הגדרות — כל מה שצריך לשנות נמצא כאן ורק כאן
//  הדיאלקט אומת מול WF-17 ו-WF-16 החיים.
// ═══════════════════════════════════════════════════════════════════
const CFG = {

  // ── מתגי בטיחות ──────────────────────────────────────────────────
  DRY_RUN: false,          // true = לא נוצרת שום רשומה. רק דוח.
  MAX_PER_RUN: 25,        // תקרת רשומות לריצה
  BRANCH: 'both',         // 'both' | 'boost' | 'renewal'

  // 🧪 מתג בדיקה בלבד. ריק = התנהגות רגילה (היום + 4 = ראשון הקרוב).
  //    ממולא בתאריך 'YYYY-MM-DD' = מחפש מחזורי בוסט שנגמרים בדיוק בתאריך הזה.
  //    ⚠️ להשאיר ריק לפני העלאה לאוויר!
  CYCLE_END_OVERRIDE: '',
  //    ומקביל לענף החידוש — תאריך סיום ליווי לחיפוש ידני.
  RENEWAL_DATE_OVERRIDE: '',

  // ── מוצרים (מאומת מ-WF-17) ───────────────────────────────────────
  PRODUCT: {
    BOOST_WORKSHOP: '2f73403a-20de-47a7-b0cb-df4761b45f21',   // ✅ סדנה בוסט
    COACHING_12W:   'd9e842a7-f284-4596-bb61-4d2a350eebb5',   // ✅ תוכנית ליווי 12 שבועות
    RETAINER:       '58a4d4f9-5921-4bfc-ba8e-518877faa375',   // ✅ ריטיינר
  },
  FALLBACK_OWNER_ID: '0fa826fa-cbc8-4ba5-9cd4-3e59f129f4de',  // ויטרו ראשי

  // ⚠️ פיירברי מחזיר picklist כ**תווית בעברית**, לא כמספר.
  //    לכן ההשוואות בקוד הן על תוויות. הכתיבה — במספר.
  ST: {
    NEW_CODE: 2,                                  // ליד חדש — לכתיבה
    SOLD:   ['ממתין לתשלום', 'עסקה נסגרה בהצלחה'],
    LOST:   ['עסקה הופסדה', 'עסקה בוטלה'],
  },
  // 🚫 מחזורי בוסט בסטטוסים האלה יידלגו לחלוטין.
  //    ערכי הסטטוס האפשריים: פתוח להרשמה · קורס פעיל · הסתיים · התבטל · ממתין לפתיחה
  CYCLE_STATUS_EXCLUDE: ['התבטל'],

  // ⚠️ שדות פיקליסט נקראים כתווית בעברית אך נכתבים כמספר.
  //    כל שדה כזה שהאוטומציה כותבת חייב להופיע כאן.
  WRITE_CODES: {
    pcfFormFilled: { 'כן': 1, 'לא': 2 },   // מילאה שאלון לאחר בוסט?
  },

  PROGRAM_BOOST_LABELS: ['בוסט'],
  COACHING_ACTIVE_LABELS: ['ליווי בתהליך'],

  // כתובת הבסיס של n8n — לבניית קישור לריצה בהערת תהליך המכירה
  N8N_BASE_URL: 'https://n8n.srv964196.hstgr.cloud',

  RETAINER_SENTINEL_YEAR: 2099,
  BOOST_CYCLE_LENGTH_DAYS: 7,
  RENEWAL_DAYS_BEFORE_END: 14,
  FOLLOWUP_HOUR: '10:00',

  // ── שמות שדות. ✅ = אומת מול workflow חי · ❓ = לא אומת ────────────
  F: {
    CYCLE_ID:    'customobject1007id',  // ✅
    CYCLE_END:   'pcfEndDate',          // ✅
    CYCLE_STAT:  'pcfStatus',           // ✅

    SALE_ID:      'opportunityid',      // ✅
    SALE_ACCOUNT: 'accountid',          // ✅
    SALE_STATUS:  'statuscode',         // ✅
    SALE_PRODUCT: 'pcfProduct',         // ✅
    SALE_CYCLE:   'pcfCourse',          // ✅
    SALE_PARENT:  'pcfParentSale',      // ✅
    SALE_GROUP:   'pcfWhatsAppToRef',   // ✅
    SALE_OWNER:   'ownerid',            // ✅
    SALE_FORMLINK:'pcfFormLink',        // ✅
    SALE_FORMFILL:'pcfFormFilled',      // ✅
    SALE_PHONE:   'pcfTelephone1',      // ✅
    SALE_EMAIL:   'pcfemailaddress',    // ✅
    SALE_FUNNEL:  'pcfFunnels',         // ✅
    SALE_CLOSED:  'pcfclosedate',       // ❓ תאריך סגירת עסקה
    SALE_FOLLOWUP:'pcfFollowUpTime',    // ❓ תאריך לפולואפ

    CO_ID:       'customobject1051id',  // ✅
    CO_ACCOUNT:  'pcfaccountid',        // ✅ ⚠️ לא accountid!
    CO_ACC_NAME: 'pcfaccountidname',    // ✅
    CO_STATUS:   'pcfStatus',           // ✅
    CO_PROGRAM:  'pcfCurrentProgram',   // ✅
    CO_ENDDATE:  'pcfEstimatedEndDate', // ✅
    CO_CYCLE:    'pcfBoostLinked',      // ✅
    CO_OWNER:    'ownerid',             // ✅
    CO_SALE:     'pcfSale',             // ✅
  },
};

function ilNow() {
  const s = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Jerusalem' });
  return new Date(s.replace(' ', 'T') + 'Z');
}
function addDays(d, n) { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x; }
function ymd(d) { return d.toISOString().slice(0, 10); }

const now = ilNow();
const trg = ($json && $json.__branch) ? $json.__branch : CFG.BRANCH;

// ── תאריכי היעד. מתג הבדיקה גובר, אם מולא. ──────────────────────
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const ovC = String(CFG.CYCLE_END_OVERRIDE || '').trim();
const ovR = String(CFG.RENEWAL_DATE_OVERRIDE || '').trim();
if (ovC && !DATE_RE.test(ovC)) {
  throw new Error('CYCLE_END_OVERRIDE לא תקין: "' + ovC + '" — הפורמט חייב להיות YYYY-MM-DD, או ריק.');
}
if (ovR && !DATE_RE.test(ovR)) {
  throw new Error('RENEWAL_DATE_OVERRIDE לא תקין: "' + ovR + '" — הפורמט חייב להיות YYYY-MM-DD, או ריק.');
}

const cycleEnd   = ovC || ymd(addDays(now, 4));                       // ראשון הקרוב
const cycleStart = ymd(addDays(new Date(cycleEnd + 'T00:00:00Z'), -CFG.BOOST_CYCLE_LENGTH_DAYS));
const renewal    = ovR || ymd(addDays(now, CFG.RENEWAL_DAYS_BEFORE_END));

return [{ json: {
  cfg: CFG,
  branch: trg,
  today:           ymd(now),
  cycleEndTarget:  cycleEnd,
  cycleStartTarget:cycleStart,
  renewalTarget:   renewal,
  testMode:        !!(ovC || ovR),
  runStartedAt:    now.toISOString(),
}}];

// ═══════════════════════════════════════════════════════════════════
//  ענף 1 · שערי הסינון + עץ הכפילות המאושר
//  ⚠️ statuscode חוזר כתווית בעברית — כל ההשוואות על תוויות.
// ═══════════════════════════════════════════════════════════════════
const meta = $('⚙️ הגדרות').first().json;
const cfg  = meta.cfg;
const F    = cfg.F;

const rows = (a) => {
  const d = (a && a.data) ? a.data : a;
  return (d && (d.Data || d.data)) || (Array.isArray(d) ? d : []);
};
const txt  = (v) => String(v == null ? '' : v).trim();
const dOnly= (v) => (v ? String(v).slice(0, 10) : null);

const cyclesRaw = rows($('1.1 מחזורי בוסט מסתיימים').first().json);
// 🚫 מדלגים על מחזורים בסטטוסים שהוגדרו בהגדרות (למשל "התבטל")
const excl    = cfg.CYCLE_STATUS_EXCLUDE || [];
const cycles  = cyclesRaw.filter(c => !excl.includes(String(c[F.CYCLE_STAT] || '').trim()));
const droppedCycles = cyclesRaw.length - cycles.length;
// ✅ רק עסקאות ששייכות לאחד מהמחזורים האלה רלוונטיות לריצה הזו
const validCycles = new Set(cycles.map(c => c[F.CYCLE_ID]));
const boostSal = rows($('1.2 עסקאות בוסט במחזור').first().json);
const coaching = rows($('1.3 תהליכי ליווי של הלקוחות').first().json);
const allSales = rows($('1.4 כל תהליכי המכירה של הלקוחות').first().json);
const accounts = rows($('1.4b שמות הלקוחות').first().json);
const nameByAcc = {};
for (const a of accounts) nameByAcc[a.accountid] = a.accountname;

// תחילת המחזור = תאריך הסיום פחות אורך המחזור
const cycInfoById = {};
for (const c of cycles) cycInfoById[c[F.CYCLE_ID]] =
  { name: c.name || '', end: dOnly(c[F.CYCLE_END]) };

const cycStartById = {};
for (const c of cycles) {
  const e = dOnly(c[F.CYCLE_END]);
  if (!e) continue;
  const d = new Date(e + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() - cfg.BOOST_CYCLE_LENGTH_DAYS);
  cycStartById[c[F.CYCLE_ID]] = d.toISOString().slice(0, 10);
}

const group = (arr, key) => {
  const m = {};
  for (const r of arr) { const k = r[key]; if (!k) continue; (m[k] = m[k] || []).push(r); }
  return m;
};
const coByAcc  = group(coaching, F.CO_ACCOUNT);
const salByAcc = group(allSales, F.SALE_ACCOUNT);

const out = [], skipped = [];

for (const deal of boostSal) {
  const acc = deal[F.SALE_ACCOUNT];
  const cyc = deal[F.SALE_CYCLE];
  const skip = (why, detail) => skipped.push({ לקוחה: deal.accountid_name_unused || acc, סיבה: why, פרטים: detail });

  if (!acc) { skip('אין לקוח מקושר לעסקה'); continue; }

  // ── שער · העסקה חייבת להשתייך למחזור שנמצא בריצה הזו ─────────────
  if (!cyc) { skip('לעסקת הבוסט אין מחזור מקושר'); continue; }
  if (!validCycles.has(cyc)) { skip('העסקה אינה שייכת למחזור שמסתיים היום (או שהמחזור בוטל)'); continue; }

  // ── שער · אין ללקוחה תהליך ליווי שאינו בוסט ─────────────────────
  const cos = coByAcc[acc] || [];
  const notBoost = cos.filter(c => !cfg.PROGRAM_BOOST_LABELS.includes(txt(c[F.CO_PROGRAM])));
  if (notBoost.length) { skip('כבר יש תהליך ליווי שאינו בוסט', notBoost.length); continue; }

  // ── שער · עץ הכפילות המאושר ─────────────────────────────────────
  // ⚠️ מחריגים את עסקאות הבוסט עצמן — אחרת עסקת הבוסט הנוכחית
  //    תיראה כ'נמכר השבוע' וכל מועמדת תיחסם תמיד.
  const boostGuid = String(cfg.PRODUCT.BOOST_WORKSHOP).toLowerCase();
  const sales = (salByAcc[acc] || []).filter(s =>
    String(s[F.SALE_PRODUCT] || '').toLowerCase() !== boostGuid);
  const terminal = cfg.ST.SOLD.concat(cfg.ST.LOST);

  // א · תהליך פעיל (כל סטטוס שאינו סופי — כולל "ליד חדש") ⇒ דילוג
  const active = sales.filter(s => !terminal.includes(txt(s[F.SALE_STATUS])));
  if (active.length) {
    skip('קיים תהליך מכירה פעיל', active.map(s => txt(s[F.SALE_STATUS])).join(', '));
    continue;
  }

  // ב · תהליך שנמכר ⇒ בדיקת תאריך סגירה מול תחילת המחזור
  const sold = sales.filter(s => cfg.ST.SOLD.includes(txt(s[F.SALE_STATUS])));
  const cycStart = cycStartById[cyc] || meta.cycleStartTarget;
  const fresh = sold.filter(s => { const cd = dOnly(s[F.SALE_CLOSED]); return cd && cd >= cycStart; });
  if (fresh.length) { skip('כבר קנתה ליווי בעקבות הבוסט הזה', cycStart); continue; }

  // ג · רק הופסדה/בוטלה, מכירה ישנה, או כלום ⇒ פותחים (אושר ע"י מייק)
  const co = cos[0] || {};
  out.push({
    account:     acc,
    accountName: nameByAcc[acc] || co[F.CO_ACC_NAME] || '',
    parentSale:  deal[F.SALE_ID],
    cycle:       cyc,
    cycleName:   (cycInfoById[cyc] || {}).name || '',
    cycleEnd:    (cycInfoById[cyc] || {}).end  || '',
    group:       deal[F.SALE_GROUP] || null,
    owner:       deal[F.SALE_OWNER] || cfg.FALLBACK_OWNER_ID,
    formLink:    deal[F.SALE_FORMLINK] || null,
    formFilled:  deal[F.SALE_FORMFILL] || null,
    phone:       deal[F.SALE_PHONE] || null,
    email:       deal[F.SALE_EMAIL] || null,
    funnel:      deal[F.SALE_FUNNEL] || null,
  });
}

const capped = out.slice(0, cfg.MAX_PER_RUN);

return [{ json: {
  branch: 'boost',
  dryRun: cfg.DRY_RUN,
  counts: {
    'מחזורים שנמצאו': cycles.length,
    'מחזורים שדולגו (מבוטלים)': droppedCycles,
    'עסקאות בוסט': boostSal.length,
    'עברו את כל השערים': out.length,
    'ייווצרו בריצה הזו': capped.length,
    'נחתכו בגלל התקרה': out.length - capped.length,
    'דילוגים': skipped.length,
  },
  toCreate: capped,
  skipped,
}}];

const meta = $('⚙️ הגדרות').first().json;
const cfg  = meta.cfg;
const F    = cfg.F;
const src  = $json;

if (!src.toCreate || !src.toCreate.length) {
  return [{ json: Object.assign({}, src, { payloads: [], note: 'אין רשומות ליצירה' }) }];
}

// ── קישור לריצה ב-n8n + פורמט תאריך עברי ─────────────────────────
const execId = (typeof $execution !== 'undefined' && $execution && $execution.id)
  ? String($execution.id) : '';
const wfId   = (typeof $workflow  !== 'undefined' && $workflow  && $workflow.id)
  ? String($workflow.id)  : '';
const runLink = (execId && wfId)
  ? cfg.N8N_BASE_URL + '/workflow/' + wfId + '/executions/' + execId
  : (cfg.N8N_BASE_URL + '/workflow/' + wfId);
const il = (ymd) => { if (!ymd) return '—';
  const p = String(ymd).slice(0,10).split('-'); return p[2] + '.' + p[1] + '.' + p[0]; };

const d = new Date(meta.runStartedAt);
d.setUTCDate(d.getUTCDate() + 1);                       // חמישי
const followup = d.toISOString().slice(0, 10) + 'T' + cfg.FOLLOWUP_HOUR + ':00';

const payloads = src.toCreate.map(r => {
  const b = {};
  b.name              = 'מכירת ליווי לאחר בוסט - ' + (r.accountName || r.account);
  b[F.SALE_ACCOUNT]   = r.account;
  b.statuscode        = cfg.ST.NEW_CODE;                // ליד חדש — נכתב כמספר
  b[F.SALE_PRODUCT]   = cfg.PRODUCT.COACHING_12W;
  b[F.SALE_PARENT]    = r.parentSale;
  if (r.cycle)      b[F.SALE_CYCLE]    = r.cycle;
  if (r.group)      b[F.SALE_GROUP]    = r.group;
  if (r.owner)      b[F.SALE_OWNER]    = r.owner;
  if (r.formLink)   b[F.SALE_FORMLINK] = r.formLink;
  // ⚠️ פיירברי מחזירה 'כן' אבל דורשת 1 בכתיבה
  if (r.formFilled) {
    const map = (cfg.WRITE_CODES || {})[F.SALE_FORMFILL] || {};
    const code = map[String(r.formFilled).trim()];
    if (code !== undefined) b[F.SALE_FORMFILL] = code;
  }
  if (r.phone)      b[F.SALE_PHONE]    = r.phone;
  if (r.email)      b[F.SALE_EMAIL]    = r.email;
  if (r.funnel)     b[F.SALE_FUNNEL]   = r.funnel;
  b[F.SALE_FOLLOWUP]  = followup;

  // ── הערה אוטומטית לנציגה ──────────────────────────────────────
  b.description = [
    '🤖 תהליך המכירה הזה נפתח אוטומטית.',
    '',
    'הסיבה: הלקוחה סיימה את מחזור הבוסט "' + (r.cycleName || '—') + '"',
    'שהסתיים בתאריך ' + il(r.cycleEnd) + ', ולא נמצא לה תהליך מכירה פעיל',
    'ולא רכישת ליווי בעקבות המחזור הזה.',
    '',
    '📞 נדרש: ליצור קשר עם הלקוחה להשלמת מכירת הליווי.',
    '',
    '───────────────',
    'נוצר על ידי WF-19 · ריצה ' + (execId || '—'),
    runLink,
  ].join('\n');

  return { accountName: r.accountName, account: r.account, body: b };
});

// ⚠️ פיירברי לא מקבלת מערך ב-POST — חייבים רשומה אחת לכל קריאה.
//    לכן מחזירים פריט נפרד לכל רשומה, וכל פריט נושא גם את הסיכום.
const base = Object.assign({}, src, { followupDate: followup, payloads });
return payloads.map(p => ({ json: Object.assign({}, base,
  { accountName: p.accountName, account: p.account, body: p.body }) }));

// ═══════════════════════════════════════════════════════════════════
//  ענף 2 · סוף ליווי ← תהליך מכירה לחידוש
// ═══════════════════════════════════════════════════════════════════
const meta = $('⚙️ הגדרות').first().json;
const cfg  = meta.cfg;
const F    = cfg.F;

const rows = (a) => {
  const d = (a && a.data) ? a.data : a;
  return (d && (d.Data || d.data)) || (Array.isArray(d) ? d : []);
};
const txt  = (v) => String(v == null ? '' : v).trim();
const dOnly= (v) => (v ? String(v).slice(0, 10) : null);

const coaching = rows($('2.1 ליוויים שמסתיימים בחלון הקרוב').first().json);
const allSales = rows($('2.2 כל תהליכי המכירה של הלקוחות').first().json);

const salByAcc = {};
for (const s of allSales) {
  const k = s[F.SALE_ACCOUNT]; if (!k) continue;
  (salByAcc[k] = salByAcc[k] || []).push(s);
}

const out = [], skipped = [];

for (const co of coaching) {
  const acc = co[F.CO_ACCOUNT];
  const nm  = co[F.CO_ACC_NAME] || acc;
  const skip = (why, detail) => skipped.push({ לקוחה: nm, סיבה: why, פרטים: detail });
  if (!acc) { skip('אין לקוח מקושר לליווי'); continue; }

  // ⚠️ סינון ריטיינרים — תאריך סיום בשנת 2099 ומעלה
  const end = dOnly(co[F.CO_ENDDATE]);
  if (end && Number(end.slice(0, 4)) >= cfg.RETAINER_SENTINEL_YEAR) {
    skip('ריטיינר — אין תאריך סיום אמיתי', end); continue;
  }
  if (!cfg.COACHING_ACTIVE_LABELS.includes(txt(co[F.CO_STATUS]))) {
    skip('הליווי אינו בסטטוס ליווי בתהליך', txt(co[F.CO_STATUS])); continue;
  }

  // ⚠️ מחריגים את עסקאות הבוסט עצמן — אחרת עסקת הבוסט הנוכחית
  //    תיראה כ'נמכר השבוע' וכל מועמדת תיחסם תמיד.
  const boostGuid = String(cfg.PRODUCT.BOOST_WORKSHOP).toLowerCase();
  const sales = (salByAcc[acc] || []).filter(s =>
    String(s[F.SALE_PRODUCT] || '').toLowerCase() !== boostGuid);
  const terminal = cfg.ST.SOLD.concat(cfg.ST.LOST);
  const active = sales.filter(s => !terminal.includes(txt(s[F.SALE_STATUS])));
  if (active.length) {
    skip('קיים תהליך מכירה פעיל', active.map(s => txt(s[F.SALE_STATUS])).join(', '));
    continue;
  }
  // ✅ החלטת מייק (16.8): רק רכישה של תוכנית ההמשך עצמה חוסמת.
  //    עסקאות עבר (בוסט, ליווי) אינן חוסמות — הן הסיבה שהיא כאן מלכתחילה.
  const sold = sales.filter(s => cfg.ST.SOLD.includes(txt(s[F.SALE_STATUS])));
  const contGuid = String(cfg.PRODUCT.RETAINER).toLowerCase();
  const already = sold.filter(s =>
    String(s[F.SALE_PRODUCT] || '').toLowerCase() === contGuid);
  if (already.length) {
    skip('כבר רכשה תוכנית המשך', already.length);
    continue;
  }

  out.push({
    account: acc, accountName: nm,
    coachingId: co[F.CO_ID],
    mentor: co[F.CO_OWNER] || cfg.FALLBACK_OWNER_ID,
    endDate: end,
  });
}

const capped = out.slice(0, cfg.MAX_PER_RUN);

return [{ json: {
  branch: 'renewal',
  dryRun: cfg.DRY_RUN,
  counts: {
    'ליוויים שמסתיימים': coaching.length,
    'עברו את כל השערים': out.length,
    'ייווצרו בריצה הזו': capped.length,
    'דילוגים': skipped.length,
  },
  toCreate: capped,
  skipped,
}}];

const meta = $('⚙️ הגדרות').first().json;
const cfg = meta.cfg;
const F   = cfg.F;
const src = $json;

if (!src.toCreate || !src.toCreate.length) {
  return [{ json: Object.assign({}, src, { payloads: [], followupDate: null, note: 'אין רשומות ליצירה' }) }];
}
if (cfg.PRODUCT.RETAINER === 'REPLACE_WITH_RETAINER_GUID') {
  return [{ json: Object.assign({}, src, { payloads: [],
    error: '⛔ חסר מזהה מוצר החידוש. יש למלא אותו בנוד ההגדרות לפני הפעלה.' }) }];
}

const execId = (typeof $execution !== 'undefined' && $execution && $execution.id)
  ? String($execution.id) : '';
const wfId   = (typeof $workflow  !== 'undefined' && $workflow  && $workflow.id)
  ? String($workflow.id)  : '';
const runLink = (execId && wfId)
  ? cfg.N8N_BASE_URL + '/workflow/' + wfId + '/executions/' + execId
  : (cfg.N8N_BASE_URL + '/workflow/' + wfId);
const il = (ymd) => { if (!ymd) return '—';
  const p = String(ymd).slice(0,10).split('-'); return p[2] + '.' + p[1] + '.' + p[0]; };

const d = new Date(meta.runStartedAt);
d.setUTCDate(d.getUTCDate() + 1);
const followup = d.toISOString().slice(0, 10) + 'T' + cfg.FOLLOWUP_HOUR + ':00';

const payloads = src.toCreate.map(r => {
  const b = {};
  b.name            = 'מכירת תוכנית המשך - ' + (r.accountName || r.account);
  b[F.SALE_ACCOUNT] = r.account;
  b.statuscode      = cfg.ST.NEW_CODE;
  b[F.SALE_PRODUCT] = cfg.PRODUCT.RETAINER;
  if (r.mentor) b[F.SALE_OWNER] = r.mentor;   // המנטורית = נציגת המכירות
  b[F.SALE_FOLLOWUP] = followup;

  // ── הערה אוטומטית לנציגה ──────────────────────────────────────
  b.description = [
    '🤖 תהליך המכירה הזה נפתח אוטומטית.',
    '',
    'הסיבה: תוכנית הליווי של הלקוחה מסתיימת בתאריך ' + il(r.endDate) + ',',
    'והיא עדיין לא רכשה תוכנית המשך.',
    '',
    '📞 נדרש: ליצור קשר עם הלקוחה להשלמת מכירת תוכנית ההמשך.',
    '',
    '───────────────',
    'נוצר על ידי WF-19 · ריצה ' + (execId || '—'),
    runLink,
  ].join('\n');

  return { accountName: r.accountName, account: r.account, body: b };
});

const base = Object.assign({}, src, { payloads, followupDate: followup });
return payloads.map(p => ({ json: Object.assign({}, base,
  { accountName: p.accountName, account: p.account, body: p.body }) }));

// ═══════════════════════════════════════════════════════════════════
//  📋 סיכום הריצה — פתח את הנוד הזה אחרי הרצה ידנית
// ═══════════════════════════════════════════════════════════════════
const S   = $('⚙️ הגדרות').first().json;
const cfg = S.cfg;

const L = [];
L.push(cfg.DRY_RUN ? '🟡 מצב הרצה יבשה — לא נוצרה שום רשומה'
                   : '🔴 מצב חי — נוצרו רשומות בפועל');
if (S.testMode) {
  L.push('🧪 מצב בדיקה פעיל — התאריכים נדרסו ידנית:');
  L.push('   סיום מחזור בוסט שמחפשים: ' + S.cycleEndTarget);
  L.push('   סיום ליווי שמחפשים: ' + S.renewalTarget);
  L.push('   ⚠️ לרוקן את מתגי הבדיקה בהגדרות לפני העלאה לאוויר!');
} else {
  L.push('תאריכי היעד: סיום מחזור ' + S.cycleEndTarget + ' · סיום ליווי ' + S.renewalTarget);
}
L.push('');

// ⚠️ קוראים ישירות מהבנאים — כך הסיכום אמין גם כשקריאת HTTP נכשלה
const pull = (node) => { try { return $(node).first().json; } catch (e) { return null; } };
const branches = [
  { title: '━━ ענף 1 · סוף בוסט ← ליווי ━━',  data: pull('1.6 בניית הרשומות') },
  { title: '━━ ענף 2 · סוף ליווי ← חידוש ━━', data: pull('2.4 בניית הרשומות') },
];

// שגיאות HTTP שהגיעו מנודי היצירה
const errs = $input.all().map(i => i.json)
  .filter(j => j && j.error)
  .map(j => (j.error && j.error.message) ? j.error.message : String(j.error));

let any = false;
for (const b of branches) {
  const r = b.data;
  if (!r || !r.branch) continue;
  any = true;
  L.push(b.title);
  for (const k in (r.counts || {})) L.push('   ' + k + ': ' + r.counts[k]);
  if (r.error) L.push('   ⛔ ' + r.error);
  if (r.payloads && r.payloads.length) {
    L.push((cfg.DRY_RUN ? '   ✅ רשומות שייווצרו:' : '   ✅ רשומות שנוצרו:'));
    for (const p of r.payloads) L.push('      • ' + (p.accountName || p.account));
  }
  if (r.skipped && r.skipped.length) {
    const gg = {};
    for (const s of r.skipped) gg[s['סיבה']] = (gg[s['סיבה']] || 0) + 1;
    L.push('   ⏭️ דילוגים:');
    for (const k in gg) L.push('      • ' + k + ': ' + gg[k]);
  }
  L.push('');
}
if (!any) L.push('לא הגיעו נתונים משום ענף — בדוק את נודי ה-HTTP.');
if (errs.length) {
  L.push('⛔ שגיאות מפיירברי בשלב היצירה:');
  for (const e of errs) L.push('   • ' + String(e).slice(0, 300));
  L.push('   הרשומות האלה לא נוצרו.');
}

return [{ json: { 'סיכום': L.join('\n'), 'שגיאות': errs,
                  'גולמי': branches.map(b => b.data).filter(Boolean) } }];

// ═══════════════════════════════════════════════════════════════════
//  1.9 · השלמת השדות שפיירברי מפילה ביצירה
//  ⚠️ אומת אמפירית (16.8): שלושה שדות לא נשמרים ב-POST —
//     שם העסקה · טלפון · אימייל. PUT אחרי היצירה כן עובד,
//     אבל רק אחרי שהאוטומציה הפנימית של פיירברי סיימה לרוץ
//     (לכן יש צומת המתנה לפני השלב הזה).
// ═══════════════════════════════════════════════════════════════════
const created = $input.all().map(i => i.json);
const built   = $('1.6 בניית הרשומות').first().json;
const bodies  = (built.payloads || []).map(p => p.body || {});

const rows = [];
created.forEach((c, i) => {
  const rec = (c && c.data && c.data.Record) || null;
  const id  = rec && rec.opportunityid;
  const b   = bodies[i];
  if (!id || !b) return;
  const patch = {};
  if (b.name)            patch.name            = b.name;
  if (b.pcfTelephone1)   patch.pcfTelephone1   = b.pcfTelephone1;
  if (b.pcfemailaddress) patch.pcfemailaddress = b.pcfemailaddress;
  if (b.description)     patch.description     = b.description;
  if (Object.keys(patch).length) rows.push({ id, patch, name: patch.name || '' });
});
return rows.map(r => ({ json: r }));   // ריק = הצמתים הבאים מדולגים

// ═══════════════════════════════════════════════════════════════════
//  2.7 · השלמת שם העסקה
//  ⚠️ פיירברי דורסת את שם העסקה כמה שניות אחרי היצירה
//     (אוטומציה פנימית). לכן PUT אחרי המתנה.
// ═══════════════════════════════════════════════════════════════════
const created = $input.all().map(i => i.json);
const built   = $('2.4 בניית הרשומות').first().json;
const bodies  = (built.payloads || []).map(p => p.body || {});
const rows = [];
created.forEach((c, i) => {
  const rec = (c && c.data && c.data.Record) || null;
  const id  = rec && rec.opportunityid;
  const b   = bodies[i];
  if (!id || !b || !b.name) return;
  const patch = { name: b.name };
  if (b.description) patch.description = b.description;
  rows.push({ id, patch, name: b.name });
});
return rows.map(r => ({ json: r }));
